create extension if not exists pgcrypto;
create type public.correction_status as enum ('submitted','under_review','awaiting_participant','partially_approved','approved','rejected','closed');
create type public.pending_owner as enum ('participant','administration');
create table public.certificate_correction_requests (id uuid primary key default gen_random_uuid(), protocol text not null unique, participant_id uuid not null references auth.users(id), certificate_id uuid not null, status public.correction_status not null default 'submitted', justification text not null, response_due_at timestamptz, last_activity_at timestamptz not null default now(), closed_at timestamptz, created_at timestamptz not null default now());
create table public.certificate_correction_items (id uuid primary key default gen_random_uuid(), request_id uuid not null references public.certificate_correction_requests(id) on delete cascade, field_name text not null, requested_value text not null, decision text, decision_reason text, decided_at timestamptz);
create table public.certificate_complementations (id uuid primary key default gen_random_uuid(), request_id uuid not null references public.certificate_correction_requests(id) on delete cascade, requested_by uuid not null references auth.users(id), description text not null, justification text not null, response_due_at timestamptz not null, status text not null default 'open', created_at timestamptz not null default now(), responded_at timestamptz);
create table public.certificate_deadline_changes (id uuid primary key default gen_random_uuid(), complementation_id uuid not null references public.certificate_complementations(id) on delete cascade, change_type text not null check(change_type in ('extension','reopening')), previous_due_at timestamptz not null, new_due_at timestamptz not null, justification text not null, normative_basis text, administrator_id uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.correction_monitoring (id uuid primary key default gen_random_uuid(), request_id uuid not null unique references public.certificate_correction_requests(id) on delete cascade, pending_owner public.pending_owner not null, next_check_at timestamptz not null, alert_level text not null default 'normal', last_alert_at timestamptz, alert_count integer not null default 0, created_at timestamptz not null default now());
alter table public.certificate_correction_requests enable row level security;
alter table public.certificate_correction_items enable row level security;
alter table public.certificate_complementations enable row level security;
alter table public.certificate_deadline_changes enable row level security;
alter table public.correction_monitoring enable row level security;
create policy "participants read own requests" on public.certificate_correction_requests for select to authenticated using ((select auth.uid())=participant_id);
create policy "participants create own requests" on public.certificate_correction_requests for insert to authenticated with check ((select auth.uid())=participant_id);
create policy "participants read own items" on public.certificate_correction_items for select to authenticated using (exists(select 1 from public.certificate_correction_requests r where r.id=request_id and r.participant_id=(select auth.uid())));
create policy "participants read own complements" on public.certificate_complementations for select to authenticated using (exists(select 1 from public.certificate_correction_requests r where r.id=request_id and r.participant_id=(select auth.uid())));
create index on public.certificate_correction_requests(status,last_activity_at);
create index on public.correction_monitoring(next_check_at,alert_level);

